        "Usual interstisyel pnömoni": "Usual interstisyel pnömonide subplevral-bazal fibrozis, bal peteği akciğer ve fibroblast odakları beklenir; difüzyon azalması restriktif paternle birliktedir. Bu hastada obstrüktif solunum testi, üst zon saydamlık artışı ve belirgin fibrozis olmadan septal yıkım UIP yerine amfizematöz süreci destekler.",
