      "question": "Bu tabloda baskın olan nekroz paterni aşağıdakilerden hangisidir?",
      "explanation": "Uzun süreli analjezik kullanımı ve diyabet renal medullanın iskemiye yatkınlığını artırır. Yan ağrısı, hematüri, kaliks içine dökülen doku parçası ve papilla mimarisini koruyan eozinofilik nekrotik alanlar renal papiller nekroz paternini destekler.",
