        "Akut kortikal nekroz": "Akut kortikal nekroz genellikle obstetrik komplikasyonlar, ağır şok veya DIC sonrası böbrek korteksinde yaygın iskemik nekrozla seyreder. Bu vakada nekrozun korteksten çok medüller papilla ve kaliks içine dökülen doku parçalarıyla ilişkili olması kortikal nekroza uymaz.",
