        "Likefaksiyon nekrozu": "Likefaksiyon nekrozu özellikle beyin infarktı veya apselerde dokunun enzimatik sindirimiyle sıvılaşması şeklinde görülür. Böbrek papillasında korunan doku silüetiyle giden iskemik nekroz ve kalsifikasyon bulguları bu sıvılaşma paterninden farklıdır.",
        "Fibrinoid nekroz": "Fibrinoid nekroz immün aracılı vaskülit veya ağır hipertansiyonda damar duvarında parlak eozinofilik fibrin benzeri materyal birikimiyle tanınır. Bu hastada temel lezyon damar duvarında değil, renal papilla dokusunun iskemik nekrozu ve üriner sisteme dökülen nekrotik parçalarıdır."
