    "examPearl": "Kolloid kenarında scalloping + diffüz hiperplastik folikül + orbitopati birlikteyse mekanizma bez yıkımı değil reseptör uyarımıdır.",
    "whyCorrect": "Tremor, taşikardi, proptozis ve diffüz guatrın yanında histolojide kolloid rezorpsiyonu ve hiperplastik folikül epiteli görülmesi TSH reseptör uyarımıyla uyumlu patolojik zemini gösterir.",
    "optionComparison": {
      "Tiroid foliküllerinde destrüktif lenfositik hasar": "Tiroid foliküllerinde destrüktif lenfositik hasar kronik otoimmün tiroidit veya ağrılı subakut tiroidit tablolarında hormon salınımı ve sonrasında hipotiroidi ile ilişkilidir. Bu vakada diffüz büyüme, orbitopati, belirgin damarlaşma ve scalloping içeren hiperfonksiyon paterni destrüksiyondan çok reseptör uyarımını destekler.",
      "TSH reseptörünü uyaran otoantikor aracılı foliküler hiperfonksiyon": "Bu seçenek en uygundur; foliküler epitelde diffüz hiperplazi, kolloid kenarında rezorpsiyon boşlukları ve klinikte orbitopati ile tremor, TSH reseptörünü uyaran otoantikorların oluşturduğu sürekli uyarım paternini açıklar. Bu mekanizma glandı yıkmak yerine hormon sentezini ve foliküler hücre aktivitesini artırır.",
      "İyot eksikliğine bağlı kompansatuvar kolloid birikimi": "İyot eksikliğine bağlı kompansatuvar kolloid birikimi endemik guatrda geniş kolloid dolu foliküller ve düzensiz nodüler büyüme ile beklenir. Bu hastada kolloid birikimi değil, kolloid rezorpsiyonu ve hiperplastik folikül epiteli ön plandadır; ayrıca orbitopati bu mekanizmayı desteklemez.",
      "Parafoliküler C hücrelerinden kalsitonin salgılayan tümör gelişimi": "Parafoliküler C hücrelerinden kalsitonin salgılayan tümör gelişimi medüller tiroid karsinomu ile ilişkilidir ve amiloid benzeri stromal madde ile kalsitonin pozitifliği beklenir. Bu vakada diffüz hiperfonksiyon bulguları ve foliküler hiperplazi vardır; nodüler C hücre tümörü paterni verilmemiştir.",
      "Kapsül ve damar invazyonu gösteren foliküler epitel neoplazisi": "Kapsül ve damar invazyonu gösteren foliküler epitel neoplazisi foliküler karsinom ayrımında kullanılır. Burada tek nodül ve invazyon değil, diffüz tiroid büyümesi, hiperfonksiyon kliniği ve kolloid rezorpsiyonuyla giden otoimmün uyarım paterni vardır."
    },
