        "Mezangial IgA birikimiyle giden proliferatif glomerüler süreç": "Mezangial IgA birikimiyle giden süreç üst solunum yolu enfeksiyonundan kısa süre sonra tekrarlayan makroskopik hematüri ile tipiktir. Bu vakada belirgin ateş, yan ağrısı, piyüri ve nötrofilik tübül infiltrasyonu ön plandadır; mezangial immün depo paterni verilmemiştir.",
