      "Th1-makrofaj aktivasyonu ile kompakt granülom oluşması": "Th1-makrofaj aktivasyonu ile kompakt granülom oluşumu tüberküloz, sarkoidoz veya yabancı cisim reaksiyonu gibi kronik hücresel immün yanıtlarda beklenir. Bu vakada granülom, epiteloid histiyosit kümeleri veya dev hücre baskınlığı yoktur; akut küçük damar hasarı ve nötrofilik nükleer artıklar ön plandadır."
