    "learningTarget": "Hiperpotasemi, hiperfosfatemi, hipokalsemi, hiperürisemi ve akut böbrek hasarının ortak hücre yıkımı mekanizmasıyla nasıl bağlandığını ayırt edebilme.",
    "demographics": "46 yaşında erkek hasta",
    "setting": "Hematoloji servisi",
    "chiefComplaint": "Hasta, lenfoma tedavisinden sonra gelişen bulantı, halsizlik, kas krampları ve çarpıntı nedeniyle serviste yeniden değerlendiriliyor.",
    "stem": "Diffüz büyük B hücreli lenfoma tanısıyla servise yatırılan hasta, boyun ve batında belirgin kitle yükü nedeniyle ilk kemoterapi kürünü almıştır. Tedaviden sonraki ikinci gün bulantısının arttığını, bacaklarında kramp ve göğsünde düzensiz çarpıntı hissettiğini söyler. Öncesinde bilinen kronik böbrek hastalığı yoktur; evde potasyum takviyesi, ACE inhibitörü veya spironolakton kullanmamaktadır. Tedavi öncesinde gece terlemesi ve kilo kaybı belirgindir, son günlerde oral alımı azalmıştır. İdrar miktarının sabaha göre azaldığını fark etmiş, ateş veya yeni odak enfeksiyon yakınması tariflememiştir.",
