      "presentation": "Bulantı, kas krampları, çarpıntı ve idrar miktarında azalma vardır.",
      "historySummary": "İlk kemoterapi küründen yaklaşık 36 saat sonra yakınmalar başlamış; potasyum artıran ilaç veya bilinen kronik böbrek hastalığı öyküsü yoktur."
