    "stem": "Hasta son üç aydır haftada birkaç kez aniden başlayan çarpıntı, enseye vuran baş ağrısı ve yoğun terleme atakları yaşadığını anlatıyor. Ataklar genellikle 15-20 dakika sürüyor, sonrasında belirgin halsizlik ve titreme hissi kalıyor. Evde ölçtüğü tansiyon değerleri atak dışında 130-140/80-90 mmHg civarındayken, atak sırasında çok daha yüksek çıktığını söylemiş. Kafein alımı sınırlı, dekonjestan veya uyarıcı ilaç kullanmıyor; ailede erken yaşta inme öyküsü yok. Son haftalarda hafif kilo kaybı fark etmiş, ancak ishal, sürekli sıcak intoleransı veya boyunda ağrı tariflemiyor.",
