      "Tiroid sintigrafisi ve radyoaktif iyot uptake testiyle tiroid hormon üretimini değerlendirmek": "Tiroid sintigrafisi ve radyoaktif iyot uptake testi, tirotoksikozun etiyolojisini ayırmak için kullanılır. Bu hastada TSH ve serbest T4 normaldir; kilo kaybı ve çarpıntı olsa bile ataklarla gelen hipertansiyon, solukluk ve terleme tiroid hormon fazlalığından daha farklı bir fizyolojik ritim gösterir. Tiroid tetkiklerini ilk sıraya almak, mevcut normal tiroid testleri ve paroksismal adrenerjik tabloyu gözden kaçırır."
