        "coreKnowledge": "Sistemik skleroz renal krizinde ani hipertansiyon ve akut böbrek fonksiyon bozukluğu tedavi geciktirmeden ACE inhibitörüyle hedeflenir; yüksek kreatinin tek başına ACE inhibitörü başlanmasına engel değildir.",
        "whyWrong": {
          "Yüksek doz metilprednizolon pulse tedavisi başlamak": "Yüksek doz metilprednizolon bazı ciddi romatolojik alevlenmelerde, örneğin hızlı ilerleyen lupus nefriti veya ağır vaskülitte kullanılabilir. Ancak sistemik sklerozlu hastada yüksek doz glukokortikoid renal kriz riskini artırabilir ve mevcut ağır hipertansiyon-renal bozulma tablosunda ilk basamak değildir. Bu vakada otoimmün inflamatuvar nefrit kanıtından çok ani hipertansif renal vasküler kriz, hemoliz ve trombosit düşüklüğü vardır.",
          "Siklofosfamid ve yüksek doz glukokortikoid ile hızlı immünsüpresyon uygulamak": "Siklofosfamid ve yüksek doz glukokortikoid, ANCA ilişkili vaskülit veya bazı hızlı ilerleyen glomerülonefrit tablolarında uygun olabilir. Bu vakada dismorfik eritrosit/eritrosit silendiri baskın nefritik sediment, hemoptizi, ANCA pozitifliği veya düşük kompleman gibi immün glomerülonefrit verileri yoktur. Üstelik yüksek doz steroid sistemik skleroz renal krizinde zararlı olabileceği için bu seçenek tedavi hedefini yanlış seçer.",
          "Renal arter darlığı dışlanana kadar tüm renin-anjiyotensin sistem blokerlerini ertelemek": "Renal arter darlığı bazı hastalarda dirençli hipertansiyon ve böbrek fonksiyon bozukluğu yapabilir; abdominal üfürüm, yaygın ateroskleroz, ACE inhibitörü sonrası dramatik kreatinin artışı veya asimetrik böbrek boyutu gibi ipuçları beklenir. Bu hastada sistemik skleroz bulguları, mikroanjiyopatik hemoliz ve ani ağır hipertansiyon daha hedefli bir acil tablo oluşturur. ACE inhibitörünü görüntüleme tamamlanana kadar ertelemek kan basıncı ve renal damar hasarının sürmesine yol açabilir.",
          "Sadece hemodiyaliz başlamak ve antihipertansif tedaviyi kreatinin normale dönene kadar bekletmek": "Hemodiyaliz, ağır üremi, kontrolsüz hiperkalemi, volüm yükü veya asidoz gelişirse destekleyici olarak gerekebilir; ancak tek başına altta yatan renin aracılı hipertansif süreci tedavi etmez. Antihipertansif tedaviyi kreatinin normale dönene kadar bekletmek ters mantıklıdır çünkü kreatinin bozukluğu çoğu kez kontrolsüz hipertansiyon ve renal vasküler süreç nedeniyle derinleşir. Diyaliz gerekse bile ACE inhibitörü yaklaşımı çoğu hastada sürdürülür ve kan basıncı kontrolü geciktirilmez."
        }
