      "explanation": "Bu hastada düzensiz dar QRS taşiaritmi, P dalgalarının seçilememesi ve düzensiz nabız paterni atriyal fibrilasyonla uyumludur. Hemodinamik instabilite olmadığı için acil kardiyoversiyon ilk zorunlu basamak değildir. Asıl prognoz belirleyici karar, yaş, hipertansiyon ve diyabet gibi risk faktörleri nedeniyle kardiyoembolik inme riskinin oral antikoagülasyonla azaltılmasıdır. Antiplatelet tedavi veya sadece hız kontrolü bu embolik riski yeterince azaltmaz.",
      "pearls": [
        {
          "label": "Sınav notu",
          "text": "Atriyal fibrilasyonda hız kontrolü semptomu, oral antikoagülasyon ise inme riskini hedefler; yüksek riskli non-valvüler hastada antiplatelet tedavi yeterli değildir."
        }
      ],
      "optionFeedback": {
        "Sadece beta blokerle hız kontrolü sağlayıp antikoagülasyonsuz poliklinik izlemi yapmak": "Bu yaklaşım ventrikül hızını azaltarak çarpıntı, efor dispnesi ve taşikardi ilişkili semptomları rahatlatabilir; hemodinamik stabil atriyal taşiaritmilerde hız kontrolü gerçekten tedavinin önemli bir parçasıdır. Ancak bu hastada yaş, hipertansiyon, diyabet ve kadın cinsiyet gibi tromboemboli riskini belirgin artıran klinik veriler vardır. Sadece hız kontrolü yapmak, sol atriyal apendikste trombüs oluşumu ve embolik inme riskini değiştirmez. Bu seçenek, semptom kontrolünü prognoz değiştiren inme profilaksisinin yerine koyduğu için eksiktir.",
        "Asetilsalisilik asit ve klopidogrel ile inme profilaksisini yeterli kabul etmek": "İkili antiplatelet tedavi koroner stent, akut koroner sendrom veya bazı seçilmiş vasküler durumlarda kullanılabilir; fakat non-valvüler atriyal fibrilasyon kaynaklı kardiyoembolik inme riskini oral antikoagülanlar kadar etkili azaltmaz. Bu vakada troponin yüksekliği, ST elevasyonu veya yeni stent gerektiren koroner olay verisi yoktur. Antiplatelet tedaviyi antikoagülasyonun yerine koymak özellikle yaşlı, hipertansif ve diyabetik hastada korunabilir inme riskini açık bırakır.",
        "Hemodinamik stabil olduğu halde antikoagülasyonu erteleyerek acil senkronize kardiyoversiyon yapmak": "Senkronize kardiyoversiyon hipotansiyon, iskemik göğüs ağrısı, akut pulmoner ödem veya bilinç bozukluğu gibi hemodinamik instabilite bulguları varsa acil olarak doğru olabilir. Bu hastada kan basıncı korunmuş, periferik perfüzyon iyi ve akciğer bulguları akut ödem lehine değildir; ayrıca yakınmanın başlangıcı net kısa süreli değildir. Stabil ve risk skoru yüksek bir hastada antikoagülasyon stratejisini erteleyerek kardiyoversiyona odaklanmak embolik komplikasyon riskini artırabilir.",
        "DOAK ile oral antikoagülasyon başlamak ve hız kontrolünü klinik duruma göre düzenlemek": "Bu seçenek en uygundur. EKG’de düzensiz dar QRS taşiaritmi paterni ve P dalgalarının seçilememesi atriyal fibrilasyonla uyumludur; ancak asıl sınav noktası ritmin adını koymaktan çok tromboembolik riskin yönetimidir. Yaş, hipertansiyon ve diyabet bu hastayı antikoagülasyon gerektiren yüksek risk grubuna taşır. Mekanik kapak veya orta-ağır mitral stenoz verisi olmadığı için doğrudan etkili oral antikoagülan uygun bir ilk tercihtir; hız kontrolü ise semptom ve ventrikül yanıtına göre beta bloker veya nondihidropiridin kalsiyum kanal blokeriyle düzenlenebilir.",
        "Kısa süreli düşük molekül ağırlıklı heparin verip risk skoru yüksek olsa bile taburculukta kesmek": "Düşük molekül ağırlıklı heparin köprü tedavisi bazı geçiş durumlarında, perioperatif süreçlerde veya oral tedavi başlanamayan seçilmiş hastalarda kullanılabilir; fakat burada sorun kısa süreli pıhtı önleme değil kalıcı kardiyoembolik riskin azaltılmasıdır. Risk skoru yüksek olduğu halde taburculukta antikoagülasyonu kesmek, atriyal fibrilasyonun epizodik veya persistan olmasından bağımsız olarak inme riskini yetersiz yönetir. Non-valvüler atriyal fibrilasyonda uygun hasta için uzun dönem oral antikoagülasyon planı yapılmalıdır."
      },
