      "coreKnowledge": "KOAH alevlenmesinde oksijen eksikliği kadar ventilasyon yetersizliği de değerlendirilir. Asidemik hiperkapnide NIV alveoler ventilasyonu artırır; kontrollü oksijen hedefi aşırı CO2 retansiyonunu önlemek için önemlidir.",
