      "options": [
        "Yalnızca antipiretik ve intravenöz sıvı verip tiroid ilaçlarını ayaktan yeniden başlatmak",
        "İyot solüsyonunu hemen verip antitiroid ilacı klinik yanıt sonrasına bırakmak",
        "Levotiroksin yüklemesi yapıp beta blokerden kaçınmak",
        "Radyoaktif iyot tedavisini acil serviste başlatmak",
        "Beta bloker, antitiroid ilaç, glukokortikoid ve antitiroid sonrası iyot basamaklarını birlikte uygulamak"
      ],
      "question": "Bu hastada acil farmakolojik yönetim için en doğru yaklaşım aşağıdakilerden hangisidir?",
      "explanation": "Bu hastada bilinen otoimmün hipertiroidi zemininde ilaç uyumsuzluğu, enfeksiyon benzeri tetikleyici, hipertermi, belirgin taşikardi, ajitasyon, gastrointestinal yakınmalar ve ağır tirotoksik biyokimya birlikte değerlendirilmelidir. Acil tedavi adrenerjik etkileri, yeni hormon sentezini, periferik dönüşümü ve hormon salınımını birlikte hedefler. İyotun antitiroid ilaçtan sonra verilmesi gerekir; aksi halde hormon sentezi için substrat sağlayabilir. Destek tedavisi ve tetikleyici neden tedavisi bu basamakların yerine geçmez, onları tamamlar.",
      "pearls": [
        {
          "label": "Sınav notu",
          "text": "Tirotoksik krizde tedavi çok hedeflidir: beta bloker + antitiroid ilaç + steroid + antitiroidden sonra iyot; iyotun sırası kritik tuzaktır."
        }
      ],
      "optionFeedback": {
        "Yalnızca antipiretik ve intravenöz sıvı verip tiroid ilaçlarını ayaktan yeniden başlatmak": "Ateş kontrolü, sıvı desteği ve tetikleyici enfeksiyonun tedavisi ağır tirotoksik tabloda destekleyici olarak önemlidir; ancak tek başına yeterli değildir. Bu hastada hipertermi, ajitasyon, belirgin taşikardi, gastrointestinal yakınmalar ve serbest T4 yüksekliği çok sistemli bir kriz tablosu oluşturur. Ayaktan ilaç yeniden başlatma yaklaşımı, periferik adrenerjik etkileri, yeni hormon sentezini, T4-T3 dönüşümünü ve hormon salınımını aynı anda hedeflemediği için yetersiz ve tehlikelidir.",
        "İyot solüsyonunu hemen verip antitiroid ilacı klinik yanıt sonrasına bırakmak": "İyot, tiroid hormon salınımını kısa süreli olarak baskılayabilir; ancak antitiroid ilaçtan önce verilirse bezin yeni hormon sentezi için substrat sağlaması nedeniyle tabloyu kötüleştirme riski vardır. Bu nedenle iyot genellikle antitiroid ilaç verildikten sonra uygulanır. Bu vakada tek basamaklı ve yanlış sıralı iyot yaklaşımı hem patofizyolojiyi eksik hedefler hem de tedavi sıralamasını bozar.",
        "Levotiroksin yüklemesi yapıp beta blokerden kaçınmak": "Levotiroksin yüklemesi hipotiroidi koması gibi karşıt klinik durumda düşünülebilecek bir yaklaşımdır; burada TSH baskılı ve serbest T4 belirgin yüksektir. Beta blokerden kaçınmak ise taşikardi, tremor, ajitasyon ve yüksek adrenerjik aktiviteyi kontrolsüz bırakır. Astım veya şok gibi kontrendikasyon yoksa beta bloker tedavinin temel bileşenlerinden biridir.",
        "Radyoaktif iyot tedavisini acil serviste başlatmak": "Radyoaktif iyot kalıcı tedavi seçeneklerinden biri olabilir, ancak akut çok sistemli kriz anında başlangıç tedavisi değildir. Etkisinin başlaması zaman alır, ayrıca ağır tirotoksik tabloda hızlı hormon etkisini azaltmaz. Bu hastada önce dolaşım, ısı, adrenerjik yük, hormon sentezi/salınımı ve periferik dönüşüm hedeflenmelidir; kesin tedavi stabilizasyon sonrasında planlanır.",
        "Beta bloker, antitiroid ilaç, glukokortikoid ve antitiroid sonrası iyot basamaklarını birlikte uygulamak": "Bu seçenek en uygundur. Ağır tirotoksik tabloda tedavi tek bir ilaca indirgenmez; beta bloker adrenerjik etkileri kontrol eder, antitiroid ilaç yeni hormon sentezini azaltır, glukokortikoid periferik T4-T3 dönüşümünü ve olası adrenal rezerv sorununu hedefler, iyot ise antitiroid ilaçtan sonra hormon salınımını baskılamak için verilir. Sıvı, soğutma, elektrolit takibi ve tetikleyici enfeksiyonun tedavisi bu farmakolojik basamaklara eşlik eder. Sıralama özellikle iyot için kritik bir sınav noktasıdır."
      },
      "rationale": "Bu hastada bilinen otoimmün hipertiroidi zemininde ilaç uyumsuzluğu, enfeksiyon benzeri tetikleyici, hipertermi, belirgin taşikardi, ajitasyon, gastrointestinal yakınmalar ve ağır tirotoksik biyokimya birlikte değerlendirilmelidir. Acil tedavi adrenerjik etkileri, yeni hormon sentezini, periferik dönüşümü ve hormon salınımını birlikte hedefler. İyotun antitiroid ilaçtan sonra verilmesi gerekir; aksi halde hormon sentezi için substrat sağlayabilir. Destek tedavisi ve tetikleyici neden tedavisi bu basamakların yerine geçmez, onları tamamlar.",
      "whyCorrect": "Bu seçenek en uygundur. Ağır tirotoksik tabloda tedavi tek bir ilaca indirgenmez; beta bloker adrenerjik etkileri kontrol eder, antitiroid ilaç yeni hormon sentezini azaltır, glukokortikoid periferik T4-T3 dönüşümünü ve olası adrenal rezerv sorununu hedefler, iyot ise antitiroid ilaçtan sonra hormon salınımını baskılamak için verilir. Sıvı, soğutma, elektrolit takibi ve tetikleyici enfeksiyonun tedavisi bu farmakolojik basamaklara eşlik eder. Sıralama özellikle iyot için kritik bir sınav noktasıdır.",
      "managementSteps": [],
      "management": [],
      "coreKnowledge": "Tirotoksik krizde tek ilaç yeterli değildir. Tedavide adrenerjik yanıt, hormon sentezi, hormon salınımı ve periferik dönüşüm ayrı ayrı hedeflenir; iyot antitiroid ilaçtan sonra verilmelidir.",
      "whyWrong": {
        "Yalnızca antipiretik ve intravenöz sıvı verip tiroid ilaçlarını ayaktan yeniden başlatmak": "Ateş kontrolü, sıvı desteği ve tetikleyici enfeksiyonun tedavisi ağır tirotoksik tabloda destekleyici olarak önemlidir; ancak tek başına yeterli değildir. Bu hastada hipertermi, ajitasyon, belirgin taşikardi, gastrointestinal yakınmalar ve serbest T4 yüksekliği çok sistemli bir kriz tablosu oluşturur. Ayaktan ilaç yeniden başlatma yaklaşımı, periferik adrenerjik etkileri, yeni hormon sentezini, T4-T3 dönüşümünü ve hormon salınımını aynı anda hedeflemediği için yetersiz ve tehlikelidir.",
        "İyot solüsyonunu hemen verip antitiroid ilacı klinik yanıt sonrasına bırakmak": "İyot, tiroid hormon salınımını kısa süreli olarak baskılayabilir; ancak antitiroid ilaçtan önce verilirse bezin yeni hormon sentezi için substrat sağlaması nedeniyle tabloyu kötüleştirme riski vardır. Bu nedenle iyot genellikle antitiroid ilaç verildikten sonra uygulanır. Bu vakada tek basamaklı ve yanlış sıralı iyot yaklaşımı hem patofizyolojiyi eksik hedefler hem de tedavi sıralamasını bozar.",
        "Levotiroksin yüklemesi yapıp beta blokerden kaçınmak": "Levotiroksin yüklemesi hipotiroidi koması gibi karşıt klinik durumda düşünülebilecek bir yaklaşımdır; burada TSH baskılı ve serbest T4 belirgin yüksektir. Beta blokerden kaçınmak ise taşikardi, tremor, ajitasyon ve yüksek adrenerjik aktiviteyi kontrolsüz bırakır. Astım veya şok gibi kontrendikasyon yoksa beta bloker tedavinin temel bileşenlerinden biridir.",
        "Radyoaktif iyot tedavisini acil serviste başlatmak": "Radyoaktif iyot kalıcı tedavi seçeneklerinden biri olabilir, ancak akut çok sistemli kriz anında başlangıç tedavisi değildir. Etkisinin başlaması zaman alır, ayrıca ağır tirotoksik tabloda hızlı hormon etkisini azaltmaz. Bu hastada önce dolaşım, ısı, adrenerjik yük, hormon sentezi/salınımı ve periferik dönüşüm hedeflenmelidir; kesin tedavi stabilizasyon sonrasında planlanır."
      }
