    "question": "Bu hastada başlangıç tedavisi için en uygun yaklaşım aşağıdakilerden hangisidir?",
    "questionType": "initial-treatment",
    "answerTarget": "pericardial-inflammatory-chest-pain",
    "diagnosis": {
      "correct": "Yüksek doz aspirin/NSAİİ tedavisine kolşisin ve gastroproteksiyon eklemek",
      "options": [
        "Acil primer perkütan koroner girişim hazırlığı yapmak",
        "Yüksek doz aspirin/NSAİİ tedavisine kolşisin ve gastroproteksiyon eklemek",
        "Tedaviyi yalnızca düşük doz oral kortikosteroidle başlatmak",
        "Tam doz antikoagülasyon ve trombolitik tedavi uygulamak",
        "Semptomlar gerileyene kadar yalnızca proton pompa inhibitörü vermek"
      ],
      "question": "Bu hastada başlangıç tedavisi için en uygun yaklaşım aşağıdakilerden hangisidir?",
      "explanation": "Vakadaki ağrı karakteri, fizik muayene ve EKG paterni akut perikardiyal inflamasyonla uyumludur. Troponinin normal olması, lokalize karşılıklı değişiklik olmaması ve ekoda tamponad bulgusu saptanmaması başlangıçta akut koroner oklüzyon veya acil drenaj gerektiren tabloyu geri plana iter. Kontrendikasyon yoksa ilk basamak tedavi aspirin/NSAİİ temelli antiinflamatuvar yaklaşımın kolşisinle desteklenmesidir.",
      "pearls": [
        {
          "label": "Sınav notu",
          "text": "Pozisyonla ve solunumla değişen göğüs ağrısı + yaygın konkav ST elevasyonu/PR depresyonu + normal troponin kombinasyonu akut koroner oklüzyondan çok perikardiyal inflamasyon lehinedir; ilk basamak aspirin/NSAİİ + kolşisindir."
        }
      ],
      "optionFeedback": {
        "Acil primer perkütan koroner girişim hazırlığı yapmak": "Primer perkütan koroner girişim, akut koroner oklüzyon düşündüren lokalize ST elevasyonu, karşılıklı ST depresyonu, tipik basıcı göğüs ağrısı ve yükselen troponin paterni olduğunda hayat kurtarıcıdır. Bu hastada ağrı pozisyonla belirgin değişmekte, sürtünme sesi duyulmakta, EKG yaygın konkav ST elevasyonu ve PR depresyonu göstermekte, troponin normal aralıkta kalmaktadır. Bu veriler akut koroner oklüzyon algoritmasını ilk sıraya taşımaz; gereksiz invaziv işlem yerine inflamatuvar perikardiyal süreci hedefleyen tedavi seçilmelidir.",
        "Yüksek doz aspirin/NSAİİ tedavisine kolşisin ve gastroproteksiyon eklemek": "Bu seçenek en uygundur. Viral üst solunum yolu enfeksiyonunu izleyen keskin, inspirasyonla ve sırtüstü yatmakla artan, öne eğilmekle azalan göğüs ağrısı; perikardiyal sürtünme sesi; yaygın konkav ST elevasyonu ve PR depresyonu birlikte akut perikardiyal inflamasyonu destekler. Hemodinamik instabilite, geniş efüzyon, yüksek troponin veya pürülan/tüberküloz kuşku yoksa ilk basamak tedavi aspirin ya da NSAİİ üzerine kolşisin eklenmesi ve gastrointestinal korumadır. Kolşisin semptom süresini ve nüks riskini azaltır; steroid ise çoğu olguda ilk seçenek değildir çünkü nüks eğilimini artırabilir.",
        "Tedaviyi yalnızca düşük doz oral kortikosteroidle başlatmak": "Kortikosteroidler otoimmün hastalık, NSAİİ kontrendikasyonu, dirençli olgu veya belirli özel nedenlerde düşünülebilir; ancak çoğu ilk atak olguda tek başına düşük doz steroidle başlamak doğru başlangıç değildir. Steroidler inflamasyonu baskılasa da nüks riskini artırabilir ve altta yatan enfeksiyöz neden dışlanmadan uygunsuz olabilir. Bu hastada böbrek yetmezliği, aktif kanama veya NSAİİ kullanımı için güçlü kontrendikasyon verilmemiştir; bu nedenle aspirin/NSAİİ + kolşisin yaklaşımı daha uygundur.",
        "Tam doz antikoagülasyon ve trombolitik tedavi uygulamak": "Tam doz antikoagülasyon ve trombolitik tedavi akut koroner tromboz veya seçilmiş pulmoner emboli gibi trombotik acillerde kullanılır. Bu vakada göğüs ağrısı pleuritik-pozisyonel özellikte, EKG yaygın konkav değişiklikler göstermekte ve troponin normaldir; ayrıca hipotansiyon veya sağ kalp yüklenmesi gibi masif emboli verisi yoktur. Gereksiz antikoagülasyon perikardiyal efüzyon gelişirse kanamalı efüzyon/tamponad riskini artırabileceği için klinik hedefi yanlış seçer.",
        "Semptomlar gerileyene kadar yalnızca proton pompa inhibitörü vermek": "Proton pompa inhibitörü gastroözofageal reflü veya NSAİİ ile birlikte mide koruması için yararlı olabilir; ancak burada tek başına tedavi edici değildir. Hastanın ağrısı yanma-regürjitasyon tarzında değil, inspirasyon ve pozisyonla değişen keskin göğüs ağrısı şeklindedir. EKG ve oskültasyon bulguları da gastrointestinal yakınmadan çok kardiyak-perikardiyal inflamasyona işaret eder; bu nedenle sadece PPI vermek hastalığın mekanizmasını tedavi etmez."
      }
    },
