      "Tedaviyi yalnızca düşük doz oral kortikosteroidle başlatmak": "Kortikosteroidler otoimmün hastalık, NSAİİ kontrendikasyonu, dirençli olgu veya belirli özel nedenlerde düşünülebilir; ancak çoğu ilk atak olguda tek başına düşük doz steroidle başlamak doğru başlangıç değildir. Steroidler inflamasyonu baskılasa da nüks riskini artırabilir ve altta yatan enfeksiyöz neden dışlanmadan uygunsuz olabilir. Bu hastada böbrek yetmezliği, aktif kanama veya NSAİİ kullanımı için güçlü kontrendikasyon verilmemiştir; bu nedenle aspirin/NSAİİ + kolşisin yaklaşımı daha uygundur.",
