    "stem": "Hasta iki gündür sağ kaburga altında giderek artan ağrı hissettiğini, ağrının özellikle yemeklerden sonra belirginleştiğini anlatıyor. Dün gece üşüme-titreme ile ateşi yükselmiş ve sabaha karşı eşi gözlerinde sararma fark etmiş. Bulantısı var, bir kez kusmuş; kanlı kusma veya siyah dışkılama olmamış. Daha önce safra taşı söylendiğini ancak ameliyat olmadığını belirtiyor. Sabah idrarının koyulaştığını, son saatlerde halsizleştiğini ve ayağa kalkınca başının döndüğünü söylüyor.",
