    "whyCorrect": "Bu seçenek en uygundur. Serum sodyumu 112 mmol/L olan hastada konfüzyon ve nöbet benzeri olay ağır semptomlu hiponatremi kabul edilir. Amaç serum sodyumunu tamamen normale getirmek değil, ilk saatlerde beyin ödemi riskini azaltacak sınırlı ve güvenli bir artış sağlamaktır. %3 hipertonik salin bolusu, yoğun klinik izlem ve sık serum sodyum kontrolüyle uygulanmalıdır; aşırı hızlı düzeltmeden kaçınmak tedavinin ayrılmaz parçasıdır.",
    "optionComparison": {
      "Günlük sıvı alımını 1 litre ile sınırlayıp ertesi gün poliklinik kontrolü planlamak": "Sıvı kısıtlaması kronik, hafif veya orta dereceli ve belirgin nörolojik semptomu olmayan bazı övolemik hiponatremi tablolarında temel tedavi olabilir. Ancak bu hastada konfüzyon dalgalanması ve kısa nöbet benzeri olay vardır; serum sodyumu 112 mmol/L düzeyindedir. Bu durumda yalnız sıvı kısıtlaması ve ertesi gün kontrol, beyin ödemi kaynaklı akut nörolojik riskleri karşılamaz ve tedaviyi tehlikeli biçimde geciktirir.",
      "Furosemid ve serbest su alımını artırarak sodyum düzeyini yavaşça yükseltmek": "Loop diüretik bazı hiponatremi yaklaşımlarında, özellikle hipervolemik durumlarda veya hipertonik salinle birlikte seçilmiş hastalarda kullanılabilir; fakat serbest su alımını artırmak hiponatremiyi derinleştirir. Bu hastada idrar ozmolalitesi yüksek ve idrar sodyumu artmış olduğundan böbrek serbest su atılımı baskılanmıştır. Ek su vermek serum sodyumunu daha da düşürerek nörolojik bulguları ağırlaştırabilir.",
      "Tolvaptan başlatıp serum sodyum kontrolünü 24 saat sonra yapmak": "Vaptanlar seçilmiş övolemik veya hipervolemik kronik hiponatremi olgularında düşünülebilir; ancak ağır semptomlu acil tabloda ilk tercih değildir. Sodyumun kontrolsüz ve hızlı yükselmesi riski vardır, ayrıca nöbet/konfüzyon gibi ağır semptomlarda hedef ilk saatlerde güvenli sınırlı artış sağlamaktır. Bu hastada 24 saat sonra kontrol planı yetersizdir; serum sodyumu çok sık izlenmelidir.",
      "İzotonik salinle hızlı yükleme yapıp sodyum düzelene kadar takip etmemek": "İzotonik salin hipovolemik hiponatremide etkili olabilir; fakat övolemik, idrar sodyumu yüksek ve idrar ozmolalitesi yüksek bir tabloda serum sodyumunu beklenen ölçüde yükseltmeyebilir, hatta verilen sodyum idrarla atılıp su tutulumu sürerse düzelme sınırlı kalabilir. Ayrıca 'takip etmemek' bu sorudaki en tehlikeli kısımdır; ağır hiponatreminin aşırı hızlı düzeltilmesi ozmotik demiyelinizasyon riski taşır. Bu vakada acil ama kontrollü düzeltme gerekir.",
      "%3 hipertonik salin bolusu verip serum sodyumunu sık aralıklarla izlemek": "Bu seçenek en uygundur. Serum sodyumu 112 mmol/L olan hastada konfüzyon ve nöbet benzeri olay ağır semptomlu hiponatremi kabul edilir. Amaç serum sodyumunu tamamen normale getirmek değil, ilk saatlerde beyin ödemi riskini azaltacak sınırlı ve güvenli bir artış sağlamaktır. %3 hipertonik salin bolusu, yoğun klinik izlem ve sık serum sodyum kontrolüyle uygulanmalıdır; aşırı hızlı düzeltmeden kaçınmak tedavinin ayrılmaz parçasıdır."
    },
