    "question": "Bu hastada acil tıbbi stabilizasyonda öncelikli yaklaşım aşağıdakilerden hangisidir?",
    "questionType": "acute-vascular-emergency-management",
    "answerTarget": "acute-aortic-syndrome-impulse-control",
    "diagnosis": {
      "correct": "İntravenöz beta blokerle kalp hızını ve duvar stresini düşürmek; gerekirse ardından vazodilatör eklemek",
      "options": [
        "Sadece sublingual nitrat verip ağrı azalırsa taburculuk planlamak",
        "Heparin ve fibrinolitik tedaviyi eş zamanlı başlatmak",
        "İntravenöz beta blokerle kalp hızını ve duvar stresini düşürmek; gerekirse ardından vazodilatör eklemek",
        "Hızlı kristalloid yüklemesi ve dobutamin infüzyonuyla sistolik basıncı yükseltmek",
        "Oral kalsiyum kanal blokeri verip seri troponin sonucunu beklemek"
      ],
      "question": "Bu hastada acil tıbbi stabilizasyonda öncelikli yaklaşım aşağıdakilerden hangisidir?",
      "explanation": "Bu vakada ani başlayan şiddetli göğüs-sırt ağrısı, iki kol arasında basınç farkı, nabız asimetrisi, yeni diyastolik üfürüm ve mediasten genişliği birlikte değerlendirilmelidir. İlk tıbbi hedef kalp hızını ve sistolik basıncı kontrollü azaltarak arter duvarına binen kesme kuvvetini düşürmektir; bu nedenle intravenöz beta bloker başlangıcı vazodilatörden önce gelir. Antikoagülan veya fibrinolitik yaklaşım, damar duvarı kaynaklı kanama/rüptür riski bulunan tabloda tehlikeli olabilir.",
      "pearls": [
        "Göğüs ağrısında basınç/nabız asimetrisi ve sırta yayılan ani ağrı, klasik akut koroner sendrom algoritmasını körlemesine uygulamamayı gerektirir.",
        "Akut büyük damar acilinde beta blokerden önce vazodilatör verilmesi refleks taşikardiyle duvar stresini artırabilir."
      ],
      "optionFeedback": {
        "Sadece sublingual nitrat verip ağrı azalırsa taburculuk planlamak": "Bu yaklaşım akut koroner sendrom dışı olmayan basit anjinal ağrıda semptomu geçici azaltabilir; ancak ani başlayan, sırta yayılan yırtılır tarzda ağrı, iki kol arasında basınç farkı ve mediasten genişliği olan hastada tek başına nitrat vermek güvenli değildir. Nitrat refleks taşikardi yapabilir ve kalp hızını kontrol etmeden arter duvarındaki kesme kuvvetini azaltmaz. Ayrıca ağrının azalması, altta yatan damar duvarı patolojisinin düzeldiği anlamına gelmez; bu nedenle taburculuk ya da yalnız semptom kontrolü bu vakada ciddi hata olur.",
        "Heparin ve fibrinolitik tedaviyi eş zamanlı başlatmak": "Heparin ve fibrinolitik tedavi, seçilmiş akut koroner sendrom veya yüksek riskli pulmoner emboli gibi trombotik tablolar için düşünülür. Bu vakada iki kol arasında belirgin kan basıncı farkı, yeni diyastolik üfürüm, ani sırt ağrısı ve grafide mediasten genişliği öncelikle kanama/ruptür riski taşıyan damar duvarı acilini akla getirir. Bu bağlamda fibrinolitik veya kontrolsüz antikoagülasyon ölümcül kanama ve rüptür riskini artırabileceği için doğru ilk yaklaşım değildir.",
        "İntravenöz beta blokerle kalp hızını ve duvar stresini düşürmek; gerekirse ardından vazodilatör eklemek": "Bu seçenek en uygundur. Hastada hipertansiyon zemininde ani başlayan yırtılır tarzda göğüs-sırt ağrısı, nabız/basınç asimetrisi ve mediasten genişliği vardır; ilk tıbbi hedef arter duvarındaki dP/dt yükünü azaltmaktır. Bu nedenle esmolol veya labetalol gibi intravenöz beta blokerle kalp hızı yaklaşık 60-80/dk aralığına ve sistolik basınç düşük güvenli düzeye indirilir. Beta blokaj sağlanmadan güçlü vazodilatör vermek refleks taşikardiyle duvar stresini artırabileceğinden sıralama önemlidir; ağrı kontrolü ve cerrahi/BT anjiyo hazırlığı bu stabilizasyonla paralel yürütülür.",
        "Hızlı kristalloid yüklemesi ve dobutamin infüzyonuyla sistolik basıncı yükseltmek": "Sıvı ve inotrop, hipotansif şokta seçilmiş durumlarda gerekebilir; ancak bu hastada başlangıç sorunu hipertansiyon ve yüksek duvar stresidir. Kristalloid yüklemesi veya dobutamin kalp debisini ve kontraktiliteyi artırarak arter duvarına binen mekanik yükü artırabilir. Perfüzyon bozukluğu gelişirse hedefli resüsitasyon ayrı değerlendirilir; mevcut tabloda öncelik hız-basınç kontrolüdür.",
        "Oral kalsiyum kanal blokeri verip seri troponin sonucunu beklemek": "Oral tedavi yavaş başlar ve acil duvar stresi kontrolü için yeterli değildir. Seri troponin izlemek göğüs ağrısında önemlidir; ancak bu vakadaki basınç farkı, yeni üfürüm ve grafi bulgusu bekleme stratejisini güvenli kılmaz. Non-dihidropiridin kalsiyum kanal blokerleri beta bloker kullanılamayan seçilmiş hastalarda intravenöz hız kontrolü için düşünülebilir; burada oral ilaçla izlem doğru akut yaklaşım değildir."
      }
    },
    "shuffleOptions": false,
