    "optionComparison": "Antitrombotik seçenekler tromboz temelli acilleri, oral ilaçlar yavaş ve yetersiz kontrolü, sıvı-inotrop yaklaşımı ise hipertansif duvar stresi tablosunda yanlış fizyolojik yönü temsil eder.",
