    "question": "Bu hastada en uygun acil tedavi yaklaşımı aşağıdakilerden hangisidir?",
    "questionType": "endocrine-emergency-treatment",
    "answerTarget": "myxedema-coma-treatment",
    "diagnosis": {
      "correct": "Stres doz hidrokortizon sonrası intravenöz tiroid hormonu replasmanı ve yoğun destek tedavisi başlamak",
      "options": [
        "Yalnız oral levotiroksin başlayıp hasta uyanıklığı artana kadar serviste izlemek",
        "Stres doz hidrokortizon sonrası intravenöz tiroid hormonu replasmanı ve yoğun destek tedavisi başlamak",
        "Metimazol ve propranolol başlayıp ateş kontrolü sağlamak",
        "Sodyum hızla normale gelene kadar yüksek hacimli hipertonik salin infüzyonu vermek",
        "Sedatif tedaviyle ajitasyonu baskılayıp tiroid testlerini poliklinikte tekrarlamak"
      ],
      "question": "Bu hastada en uygun acil tedavi yaklaşımı aşağıdakilerden hangisidir?",
      "explanation": "Yaşlı hastada hipotermi, bradikardi, hipoventilasyon, hiponatremi, somnolans ve çok düşük serbest T4 ile yüksek TSH birlikte ağır dekompanse hipotiroidi tablosunu oluşturur. Enfeksiyon tetikleyici olabilir. Tedavi; yoğun bakım desteği, ventilasyon ve ısı yönetimi, stres doz hidrokortizon ve ardından intravenöz tiroid hormonu replasmanını içerir; yalnız oral tedavi veya bekleme yaklaşımı yaşamı tehdit eden fizyolojik yavaşlamayı düzeltmekte yetersizdir.",
      "pearls": [
        "Ağır hipotiroidi acilinde “koma” kelimesi tam koma şartı değildir; uykuya meyil ve organ yavaşlaması yeterince ciddidir.",
        "Steroid verilmesi, olası adrenal yetmezlik ve tiroid hormonu sonrası kortizol gereksinimi artışı nedeniyle güvenlik basamağıdır.",
        "Aktif yeniden ısıtmadan çok kontrollü/pasif ısıtma ve yoğun bakım desteği tercih edilir."
      ],
      "optionFeedback": {
        "Yalnız oral levotiroksin başlayıp hasta uyanıklığı artana kadar serviste izlemek": "Oral levotiroksin kronik hipotiroidi tedavisinin temelidir; ancak bilinç değişikliği, hipotermi, bradikardi, hipoventilasyon ve hiponatremi olan ağır dekompanse tabloda tek başına yavaş ve yetersiz kalabilir. Emilim bozulabilir, barsak motilitesi azalabilir ve yoğun bakım desteği gerekebilir. Ayrıca eşlik eden adrenal yetmezlik dışlanmadan tiroid hormonu vermek hemodinamik riski artırabileceği için stres doz steroid basamağı atlanmamalıdır.",
        "Stres doz hidrokortizon sonrası intravenöz tiroid hormonu replasmanı ve yoğun destek tedavisi başlamak": "Bu seçenek en uygundur. Hastada soğuğa tahammülsüzlük ve ilaç aksatma öyküsü üzerine enfeksiyonla tetiklenen uykuya meyil, hipotermi, bradikardi, hipoventilasyon, hiponatremi, çok yüksek TSH ve düşük serbest T4 vardır. Yönetim yoğun bakım düzeyinde destek tedavisi, pasif ısıtma, ventilasyon ve glukoz/sodyum takibini içerir; adrenal yetmezlik olasılığı nedeniyle hidrokortizon verildikten sonra intravenöz tiroid hormonu replasmanı başlanır. Bu yaklaşım hem hormon eksikliğini hem de yaşamı tehdit eden fizyolojik yavaşlamayı hedefler.",
        "Metimazol ve propranolol başlayıp ateş kontrolü sağlamak": "Metimazol ve propranolol tirotoksik kriz veya ciddi hipertiroidide kullanılır. Bu hastada taşikardi, hipertermi ve serbest T4 yüksekliği yoktur; aksine bradikardi, hipotermi, TSH yüksekliği ve düşük serbest T4 vardır. Propranolol bu tabloda bradikardiyi ve dolaşım yavaşlamasını ağırlaştırabilir; metimazol ise zaten düşük hormon üretimini daha da baskılar.",
        "Sodyum hızla normale gelene kadar yüksek hacimli hipertonik salin infüzyonu vermek": "Hiponatremi bu tabloda önemlidir; fakat temel sorun ağır hipotiroidiye bağlı su atılım bozukluğu, hipoventilasyon ve metabolik yavaşlamadır. Nöbet veya ağır serebral ödem bulgusu olmadan sodyumu hızlı normalleştirmeye çalışmak ozmotik demiyelinizasyon riskini artırabilir. Tedavi sodyumu izlemeyi ve gerekirse kontrollü düzeltmeyi içerir; ancak primer yaklaşım steroid, tiroid hormonu ve yoğun destek tedavisidir.",
        "Sedatif tedaviyle ajitasyonu baskılayıp tiroid testlerini poliklinikte tekrarlamak": "Bu hastada ajitasyon değil bilinç azalması ve metabolik yavaşlama vardır. Sedatif ilaçlar hipoventilasyonu, bradikardiyi ve mental durum bozukluğunu derinleştirebilir. Tiroid testlerinin poliklinikte tekrarlanması, hipotermi ve hipoventilasyonla gelen bir hastada güvenli değildir; acil yoğun bakım tedavisi gerekir."
      }
    },
