    "diagnosis": {
      "correct": "Nefrotik protein kaybına bağlı antitrombin III azalması ve renal venöz tromboz gelişmesi",
      "options": [
        "Nefrotik protein kaybına bağlı antitrombin III azalması ve renal venöz tromboz gelişmesi",
        "Tübüler asit sekresyon bozukluğuna bağlı kalsiyum fosfat taşının üreterde tıkanıklık yapması",
        "İmmün kompleks birikimine bağlı hızlı ilerleyen kresentik glomerüler inflamasyon gelişmesi",
        "Bakteriyel piyelonefrite bağlı renal parankimde apse ve septik emboli oluşması",
        "Renal arter duvarında fibromüsküler kalınlaşmaya bağlı akut kortikal iskemi gelişmesi"
      ],
      "question": "Bu hastadaki yeni klinik tabloyu en iyi açıklayan süreç aşağıdakilerden hangisidir?",
      "explanation": "Vakadaki masif proteinüri, ağır hipoalbuminemi, hiperlipidemi ve ödem nefrotik sendromu gösterir. Nefrotik sendromda antikoagülan proteinlerin idrarla kaybı ve pıhtılaşma faktörlerindeki dengesizlik venöz tromboz riskini artırır; ani yan ağrısı, hematüri, kreatinin artışı ve renal vende dolum defekti bu komplikasyonu destekler.",
      "pearls": [
        "Nefrotik sendrom yalnız ödem değil, hiperkoagülabilite de oluşturur.",
        "Membranöz nefropati erişkinde nefrotik sendrom ve venöz trombozla güçlü ilişkilidir.",
        "Renal venöz tromboz ani yan ağrısı, hematüri ve böbrek fonksiyon bozulmasıyla gelebilir."
      ],
      "optionFeedback": {
        "Nefrotik protein kaybına bağlı antitrombin III azalması ve renal venöz tromboz gelişmesi": "Bu seçenek en uygundur. Hastada belirgin ödem, çok yüksek proteinüri, ağır hipoalbuminemi ve hiperlipidemi nefrotik sendrom paternini gösterir; ani yan ağrısı, mikroskopik hematüri, kreatininde artış ve kontrastlı görüntülemede renal venöz dolum defekti ise bu zeminde trombotik komplikasyonu destekler. Nefrotik sendromda antitrombin III gibi antikoagülan proteinlerin idrarla kaybı, fibrinojen ve pıhtılaşma faktörlerinde artış, hemokonsantrasyon ve özellikle membranöz nefropatide yüksek tromboz riski renal ven trombozuna yol açabilir. Buradaki ana mekanizma enfeksiyon veya taş değil, protein kaybına bağlı hiperkoagülabilitedir.",
        "Tübüler asit sekresyon bozukluğuna bağlı kalsiyum fosfat taşının üreterde tıkanıklık yapması": "Kalsiyum fosfat taşı yan ağrısı ve hematüri yapabilir; distal renal tübüler asidoz gibi durumlarda tekrarlayan taş görülebilir. Ancak bu hastada masif proteinüri, albumin 1.8 g/dL, yaygın ödem ve venöz dolum defekti vardır. Taş hastalığında bu düzeyde nefrotik proteinüri ve hipoalbuminemi beklenmez; ayrıca görüntülemede üreter taşı veya hidronefroz değil venöz tıkanma paterni verilmiştir.",
        "İmmün kompleks birikimine bağlı hızlı ilerleyen kresentik glomerüler inflamasyon gelişmesi": "Kresentik glomerülonefrit hızlı kreatinin artışı, aktif idrar sedimenti, eritrosit silendirleri ve sıklıkla hipertansiyon/oligüri ile seyreder. Bu vakada proteinüri nefrotik düzeydedir fakat sedimentte eritrosit silendiri baskınlığı verilmemiştir; asıl yeni olay yan ağrısı ile birlikte renal venöz dolum defektidir. İmmün kompleks/kresentik inflamasyon bu kadar belirgin hipoalbuminemiye bağlı tromboz riskini ve görüntüleme bulgusunu açıklamakta ikincil kalır.",
        "Bakteriyel piyelonefrite bağlı renal parankimde apse ve septik emboli oluşması": "Piyelonefrit ateş, kostovertebral açı hassasiyeti, piyüri, bakteriüri ve sıklıkla yüksek inflamatuvar belirteçlerle beklenir; renal apse daha toksik bir tablo oluşturur. Bu hastada ateş tariflenmemiş, idrar nitrit/lökosit esterazı ön planda değildir ve asıl zemin nefrotik sendromdur. Septik emboli veya apse, masif proteinüri-hipoalbuminemi-venöz dolum defekti zincirini açıklamaz.",
        "Renal arter duvarında fibromüsküler kalınlaşmaya bağlı akut kortikal iskemi gelişmesi": "Fibromüsküler displazi genç kadınlarda sekonder hipertansiyon ve renal arter stenozu ile ilişkilidir; akut yan ağrısı yapabilir ama temel bulgu renovasküler hipertansiyondur. Bu vakada ağır nefrotik sendrom, venöz dolum defekti ve hipoalbuminemi vardır. Renal arter kaynaklı kortikal iskemi, nefrotik protein kaybına bağlı hiperkoagülabilite ve renal venöz tıkanıklık paternini açıklamaz."
      }
    },
